// Shadowing / Dictation player (= theieltsdictionary.com/practice/speaking/shadowing/<id>?mode=...).
// Layout, class names and copy follow the site's player chunk (scripts/tid/build_speaking.raw/shadowing-player-chunk.pretty.js);
// styles come from the site's stylesheet scoped under .shp (shadowPlayer.css, generated by build_speaking.js).
// Server features are replaced locally: Web Speech API transcript + word alignment instead of /api/transcribe,
// app dictionary instead of /api/vocab-word, ttsService instead of /api/tts. Results live in localStorage.
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Volume2, X, SkipBack, SkipForward, RotateCcw, Maximize2, Minimize2, Loader2, Mic, Headphones, ChevronRight, BookmarkPlus, Check } from 'lucide-react';
import './shadowPlayer.css';
import { asset } from '../shared';
import { dictionaryService } from '../../../services/dictionaryService';
import { useLocalData, loadShadowing, speak, compareSentence, hasSpeechRecognition, addHistory } from './speakingUtils';
import { useYouTube } from './useYouTube';

const SR = typeof window !== 'undefined' ? (window.SpeechRecognition || window.webkitSpeechRecognition) : null;
const LOW = ['Vẫn còn hơi lạc trôi, nhưng luyện thêm là ổn áp nha.', 'Mới khởi động thôi mà, mai chiến tiếp nha!', 'Chưa xong hết nhưng chăm thế này là có tương lai lắm đó.'];
const MID = ['Quá nửa chặng đường rồi, đỉnh thật sự!', 'Tai nghe của bạn hôm nay làm việc hết công suất luôn.', 'Cỡ này thì examiner cũng phải dè chừng á nha.'];
const TOP = ['Hoàn thành 100%?? Cho xin chữ ký với!!', 'Giỏi quá trời giỏi, khoe ngay đi chờ chi!', 'Bài này đã bị bạn phá đảo. Respect!'];
const FLU_LABEL = { slow: 'Chậm hơn bản xứ — thử đọc liền mạch hơn', fast: 'Nhanh hơn bản xứ — dễ nuốt âm, đọc chậm lại chút', ok: 'Nhịp đọc bám sát bản xứ 👏' };
const STAR = 'M12 1c.5 5.5 5 10 10.5 10.5C17 12 12.5 16.5 12 22c-.5-5.5-5-10-10.5-10.5C7 11 11.5 6.5 12 1z';

const fmtSecs = e => {
  if (e < 60) return `${e} giây`;
  const h = Math.floor(e / 3600), m = Math.floor((e % 3600) / 60), s = String(e % 60).padStart(2, '0');
  return h > 0 ? `${h} giờ ${m} phút` : `${m} phút ${s} giây`;
};
const readJSON = (k, d) => { try { return JSON.parse(localStorage.getItem(k) || 'null') ?? d; } catch { return d; } };
const writeJSON = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* storage full */ } };
const stripAccents = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');

// Local stand-in for the site's evaluatePronunciation + scoreFluency (score = 70% accuracy + 30% fluency).
function evaluate(spoken, target, speechSeconds, nativeSeconds) {
  const { score: accuracy, words } = compareSentence(target, spoken);
  let fluency = null, fluVerdict = null;
  if (nativeSeconds > 0 && speechSeconds > 0) {
    const r = speechSeconds / nativeSeconds;
    fluVerdict = r > 1.6 ? 'slow' : r < 0.7 ? 'fast' : 'ok';
    fluency = Math.max(0, Math.min(100, Math.round(r > 1.6 ? 100 - (r - 1.6) * 60 : r < 0.7 ? 100 - (0.7 - r) * 150 : 100)));
  }
  return {
    score: fluency == null ? accuracy : Math.round(accuracy * 0.7 + fluency * 0.3),
    accuracy, fluency, fluVerdict, algo: 2, spokenText: spoken,
    wordResults: words.map(w => ({ word: w.w, status: w.ok ? 'correct' : 'wrong' })),
  };
}

// Dictionary popup (site: word modal with Tiếng Việt box + "lưu vào sổ")
function WordModal({ word, context, onClose, onSaveWord }) {
  const [data, setData] = useState(null);
  const [state, setState] = useState('loading');
  const [saved, setSaved] = useState(false);
  useEffect(() => {
    let off = false;
    dictionaryService.lookup(word).then(d => { if (!off) { setData(d); setState('ok'); } }).catch(() => !off && setState('error'));
    return () => { off = true; };
  }, [word]);
  const save = () => {
    if (!data || saved) return;
    onSaveWord?.({
      word: data.word || word, ipa: data.ipaUs || data.ipaUk || '', partOfSpeech: data.partOfSpeech || 'noun', meaningVi: data.meaningVi || '',
      meaningEn: data.lexicalMeanings?.[0]?.definitions?.[0]?.definition || '',
      examples: context ? [{ en: context, vi: '', context: 'IELTS Shadowing' }] : [], synonyms: data.synonyms || [], tags: ['IELTS', 'Speaking'],
    });
    setSaved(true);
  };
  const def = data?.lexicalMeanings?.[0]?.definitions?.[0]?.definition;
  return (
    <div className="tid-root fixed inset-0 z-[10050] flex items-center justify-center p-4" onClick={onClose}>
      <div className="absolute inset-0 bg-black/40" />
      <div className="relative w-full max-w-sm rounded-[28px] border border-slate-100 bg-white p-6 text-slate-900 shadow-2xl" onClick={e => e.stopPropagation()}>
        <button onClick={onClose} className="absolute right-4 top-4 text-slate-400 transition-colors hover:text-slate-800"><X size={18} /></button>
        <div className="mb-3 flex items-center gap-3 pr-6">
          <h4 className="text-xl font-black capitalize text-slate-800">{word}</h4>
          <button onClick={() => speak(word, 'American')} className="text-herb-600 transition-transform hover:scale-110"><Volume2 size={20} /></button>
        </div>
        {state === 'loading' ? (
          <div className="animate-pulse space-y-2"><div className="h-3 w-20 rounded bg-slate-200" /><div className="h-3 w-full rounded bg-slate-200" /></div>
        ) : (
          <>
            <p className="mb-3 font-mono text-sm text-herb-600">{data?.ipaUs || data?.ipaUk || '/.../'}</p>
            {data?.meaningVi && (
              <div className="mb-3 rounded-xl border border-herb-100 bg-herb-50 px-3 py-2">
                <span className="mb-0.5 block text-[9px] font-black uppercase tracking-widest text-herb-500">Tiếng Việt</span>
                <p className="text-sm font-black text-herb-700">{data.meaningVi}</p>
              </div>
            )}
            {state === 'error'
              ? <p className="mb-3 text-sm font-bold italic text-slate-500">Từ này chưa có trong từ điển bạn ơi, thử tìm từ khác nhé 🔍</p>
              : <p className="mb-4 text-sm font-bold leading-relaxed text-slate-500">{def || 'Chưa tìm thấy nghĩa bạn ơi 🤔'}</p>}
            {onSaveWord && (
              <button disabled={!data || saved} onClick={save} className={`flex h-10 w-full items-center justify-center gap-2 rounded-xl border-2 border-black text-sm font-black shadow-[3px_3px_0_rgba(0,0,0,1)] transition-all disabled:opacity-60 ${saved ? 'bg-herb-600 text-white' : 'bg-[#FFE787] text-[#1E3006] hover:-translate-y-0.5'}`}>
                {saved ? <><Check size={16} /> Đã lưu vào sổ</> : <><BookmarkPlus size={16} /> Lưu vào sổ từ vựng</>}
              </button>
            )}
          </>
        )}
      </div>
    </div>
  );
}

